const state={installPrompt:null,session:null,tab:'quote',dark:false,products:[],customers:[],verified:[],rules:[],cart:[],edit:null,selectedCustomer:null,selectedProduct:null,online:navigator.onLine,pending:[],installPrompt:null};

function arrangeLocalLayout(){const view=$("#view");if(!view)return;view.className="quote-grid";const cards=[...view.querySelectorAll(":scope > .card")];if(cards.length<7)return;["area-general","area-customer","area-product","area-cubic","area-carriers","area-services-source","area-cart"].forEach((n,i)=>cards[i]?.classList.add(n));const product=cards[2],g3=product.querySelector(".grid.g3"),g4=product.querySelector(".grid.g4");if(g3&&g4&&!product.querySelector(".product-pricing")){const items=[...g3.children],pricing=items.slice(3);pricing.forEach(x=>g3.removeChild(x));const pg=document.createElement("div");pg.className="grid g3 product-pricing";pricing.forEach(x=>pg.appendChild(x));g4.parentElement.insertBefore(pg,g4.nextElementSibling);const sku=$("#psku");if(sku&&!$("#record-id")){const l=document.createElement("label");l.innerHTML='<span class="label">RECORD ID</span><input id="record-id" class="input result" readonly>';g3.insertBefore(l,g3.children[2]||null);}}if(!$("#pverified")){const l=document.createElement("label");l.style.display="block";l.className="verified-wrap";l.innerHTML='<span class="label">VERIFIED CONFIGURATION</span><textarea id="pverified" class="textarea verified" readonly></textarea>';cards[3].appendChild(l);}const carrier=cards[4],cg=carrier.querySelector(".carrier-grid"),svc=cards[5];if(cg&&svc&&!cg.contains(svc)){svc.classList.add("embedded-service");cg.appendChild(svc);}const winner=$("#winner");if(winner&&!$("#winner-panel")){const wp=document.createElement("section");wp.id="winner-panel";wp.className="section-card winner-card area-winner";wp.innerHTML='<div class="section-title">🏆 PLATAFORMA GANADORA</div>';wp.appendChild(winner);view.appendChild(wp);}let action=view.querySelector(".action-bar");if(!action){action=document.createElement("div");action.className="action-bar";action.innerHTML='<button class="btn btn-lilac" id="database">🗄️ Data Base</button><button class="btn btn-success" id="save-quote-bottom">💾 Save Quote</button><button class="btn btn-warning" id="view-quotes">View quotes</button><button class="btn btn-primary" id="export">📤 Export</button><span class="action-spacer"></span><button class="btn btn-primary" id="toggle-note">+ Note</button><button class="btn btn-success" id="add-product">➕ Add product</button><button class="btn btn-danger" id="clear-product">🧹 Limpiar 3-5</button><button class="btn btn-danger" id="clear-all">🧨 Limpiar Todo</button>';view.appendChild(action);}const oldSave=$("#save-quote"),oldUpdate=$("#update-quote"),oldClear=$("#clear-form"),addCart=$("#add-cart"),note=$("#pnota");if(oldSave&&oldSave.parentElement!==action)action.insertBefore(oldSave,action.children[1]);if(oldUpdate&&oldUpdate.parentElement!==action)action.insertBefore(oldUpdate,action.children[1]);if(oldClear&&oldClear.parentElement!==action)action.appendChild(oldClear);if(addCart){addCart.style.display="none";$("#add-product").onclick=()=>addCart.click();}if(oldSave)$("#save-quote-bottom").onclick=()=>oldSave.click();$("#database").onclick=()=>openDatabase("products");$("#view-quotes").onclick=openQuotesModal;$("#export").onclick=openExportModal;$("#clear-product").onclick=clearProductWeb;$("#clear-all").onclick=clearAllWeb;if(note){note.classList.add("hidden","note-floating");action.insertBefore(note,$("#toggle-note"));$("#toggle-note").onclick=()=>{note.classList.toggle("hidden");if(!note.classList.contains("hidden"))note.focus();}}const custInput=$("#qcompany");if(custInput&&!$("#save-cust")){const b=document.createElement("button");b.type="button";b.id="save-cust";b.className="icon-btn";b.textContent="💾";b.title="Guardar cliente";custInput.parentElement?.appendChild(b);b.onclick=saveCustomerWeb;}if(svc&&!$("#add-services")){const b=document.createElement("button");b.id="add-services";b.className="btn btn-success w-100 mt-2";b.textContent="Add Selected";b.onclick=addSelectedServicesWeb;svc.appendChild(b);const ap=document.createElement("div");ap.className="services-apply";ap.innerHTML='<span>Apply to:</span><label class="form-check"><input id="apply-wwe" class="form-check-input" type="checkbox" checked><span class="form-check-label">WWE</span></label><label class="form-check"><input id="apply-cbcfs" class="form-check-input" type="checkbox"><span class="form-check-label">CBCFS</span></label>';const srch=svc.querySelector("#srv-search");srch?.parentElement?.insertBefore(ap,srch);}}

function updateRecordId(){const d=String($("#qdate")?.value||"").replaceAll("/",""),q=String($("#qnum")?.value||"").replace(/\s/g,""),s=String($("#psku")?.value||"").replace(/\s/g,""),n=String($("#pqty")?.value||"");const el=$("#record-id");if(el)el.value=d&&q&&s&&n?d+"_"+q+"P"+s.slice(0,4).toUpperCase()+n:"";}
function addSelectedServicesWeb(){const aw=$("#apply-wwe")?.checked,ac=$("#apply-cbcfs")?.checked;if(!aw&&!ac){toast("Selecciona WWE o CBCFS",false);return}const vals=[...document.querySelectorAll("#services input[type=checkbox]:checked")].map(x=>x.value);if(!vals.length){toast("Selecciona al menos un servicio",false);return}const old=String($("#selected-services")?.value||"").split(",").map(x=>x.trim()).filter(Boolean),out=[];vals.forEach(v=>{if(aw)out.push("WWE: "+v);if(ac)out.push("CBCFS: "+v)});$("#selected-services").value=[...new Set(old.concat(out))].join(", ");document.querySelectorAll("#services input[type=checkbox]").forEach(x=>x.checked=false);}
function saveCustomerWeb(){const company=$("#qcompany").value.trim(),address=$("#qaddress").value.trim(),type=$("#qtype").value;if(!company||!address){toast("Falta Company or Name o Address",false);return}const existing=state.customers.find(x=>norm(x.company_name)===norm(company)&&norm(x.address)===norm(address));const obj={type,company_name:company,address,accessories:$("#selected-services").value||"",local_delivery_cost_1:$("#ld_cost1")?.value||"-",local_delivery_cost_extra:$("#ld_cost_extra")?.value||"-"};(existing?sb.from("customers").update(obj).eq("id_cliente",existing.id_cliente):sb.from("customers").insert(obj)).then(async r=>{if(r.error){toast(r.error.message,false);return}const q=await sb.from("customers").select("*").order("company_name").order("address");state.customers=q.data||[];toast("Cliente guardado");});
}
function clearProductWeb(){if(!confirm("¿Limpiar campos del producto?"))return;state.selectedProduct=null;document.querySelectorAll("#pname,#psku,#record-id,#pqty,#pprice,#pweight,#pheight,#pti,#phi,#ptihi,#pdims,#pbundle,#pverified,#pconfig,#pinsured,#pnota").forEach(e=>{if(e)e.value=""});$("#prevenue").value="85";document.querySelectorAll("#pallets input").forEach(e=>{if(e.classList.contains("pal"))e.value="1";else e.value=""});["wwe_cost","wwe_add","cbcfs_cost","cbcfs_add","ups_dv","ups_sgn","ups_sm","ups_add","fedex_cost","fedex_add","uber_cost","uber_add","ld_cost1"].forEach(id=>$("#"+id)&&($("#"+id).value=""));if($("#uber_trucks"))$("#uber_trucks").value="1";calcPallets();calc();}
function clearAllWeb(){if(!confirm("¿Borrar todo y vaciar carrito?"))return;state.cart=[];state.edit=null;render();}
