function toast(m,good=true){const t=$('#toast');t.textContent=m;t.className='toast '+(good?'good':'bad');t.style.cssText='position:fixed;right:18px;bottom:18px;background:'+(good?'#137333':'#d93025')+';color:#fff;padding:11px 14px;border-radius:10px;z-index:3000;box-shadow:0 8px 30px rgba(0,0,0,.25)';setTimeout(()=>t.textContent='',2800)}
function appShell(){return `<div class="app-shell"><header class="app-topbar"><div class="brand-wrap"><img src="icon-192.svg" class="brand-icon" alt="LogiSuite"><div><div class="brand-name">LogiSuite</div><div class="brand-sub">Cotizador y gestión logística</div></div></div><div class="top-actions"><span class="status-pill ${state.online?"online":"offline"}"><i></i>${state.online?"Online":"Offline"}</span><button class="btn btn-sm theme-btn" id="theme">${state.dark?"☀️ Claro":"🌙 Oscuro"}</button><span class="user-name">${esc(state.session?.user_metadata?.display_name||"María José")}</span><button class="btn btn-sm btn-outline-secondary" id="logout">Cerrar sesión</button></div></header><main class="app-main"><div id="view"></div></main></div>`}
function render(){document.body.innerHTML=appShell();document.body.setAttribute("data-bs-theme",state.dark?"dark":"light");$("#theme").onclick=()=>{state.dark=!state.dark;localStorage.setItem("logisuite-dark",state.dark?"1":"0");render()};$("#logout").onclick=logout;$("#view").innerHTML=quoteView();arrangeLocalLayout();bindQuote();}
function quoteView(){const d=new Date();const ds=`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;return `<div class="card"><h2 class="section-title">1. General Information</h2><div class="grid g3"><label><span class="label">DATE</span><input id="qdate" class="input" value="${esc(state.edit?.date||ds)}"></label><label><span class="label"># QUOTE</span><input id="qnum" class="input" value="${esc(state.edit?.quote||'')}"></label><label><span class="label">EMAIL</span><input id="qemail" class="input" value="${esc(state.edit?.email||'')}" readonly></label></div></div>
<div class="card"><h2 class="section-title">2. Customer Information</h2><div class="grid g3"><label><span class="label">TYPE</span><select id="qtype" class="select"><option>Seleccionar</option>${['Distributor','Restaurant','Hotel','Country Club','Golf Club','Cafe','Warehouse','Residential','Local Delivery','Other','S/E'].map(x=>`<option ${state.edit?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="autocomplete"><span class="label">COMPANY OR NAME</span><input id="qcompany" class="input" autocomplete="off" value="${esc(state.edit?.company_name||'')}"><div id="suggestions" class="suggestions hidden"></div></label><label><span class="label">ZIP/ADDRESS</span><textarea id="qaddress" class="textarea">${esc(state.edit?.address||'')}</textarea></label></div><div id="customer-warning" class="muted"></div></div>
<div class="card"><h2 class="section-title">3. Product Information</h2><div class="grid g3"><label class="autocomplete"><span class="label">PRODUCT</span><input id="pname" class="input" autocomplete="off"><div id="prod-suggestions" class="suggestions hidden"></div></label><label><span class="label">SKU</span><input id="psku" class="input" readonly></label><label><span class="label">QTY</span><input id="pqty" class="input" type="number" min="0"></label><label><span class="label">PRICE X CASE</span><input id="pprice" class="input" type="number" step="0.01"></label><label><span class="label">REVENUE</span><select id="prevenue" class="select"><option>85</option><option>80</option><option>75</option></select></label><label><span class="label">INSURED VALUE</span><input id="pinsured" class="input" readonly></label></div>
<div class="grid g4" style="margin-top:10px"><label><span class="label">WEIGHT</span><input id="pweight" class="input"></label><label><span class="label">HEIGHT</span><input id="pheight" class="input"></label><label><span class="label">TI</span><input id="pti" class="input"></label><label><span class="label">HI</span><input id="phi" class="input"></label><label><span class="label">TIHI</span><input id="ptihi" class="input" readonly></label><label><span class="label">DIMENSIONS</span><input id="pdims" class="input"></label><label><span class="label">REPACK</span><select id="prepack" class="select"><option>Redondear</option><option>21x16x9</option><option>26x11x9</option><option>Otro</option></select></label><label><span class="label">VERIFIED</span><input id="pverified" class="input" readonly></label></div>
<label style="display:block;margin-top:10px"><span class="label">Bundle</span><textarea id="pbundle" class="textarea"></textarea></label>
<label style="display:block;margin-top:10px"><span class="label">Nota</span><input id="pnota" class="input" placeholder="Nota del producto..."></label></div>
<div class="card"><h2 class="section-title">4. Cubic Volume Calculator</h2><div class="grid g4"><label><span class="label">Límite de altura</span><select id="maxheight" class="select"><option>Altura Máxima: 90"</option><option>Altura Máxima: 41"</option><option>Altura Máxima: Personalizada</option></select></label><label><span class="label">Altura personalizada</span><input id="customheight" class="input" type="number" step="0.01" disabled></label><div class="row" style="align-items:end"><button class="btn secondary" id="add-pallet">+ Pallet</button><button class="btn danger" id="remove-pallet">− Pallet</button></div><div class="pill">Filas: <b id="pallet-count">1</b></div></div><div id="pallets" style="margin-top:10px"></div><div class="row" style="margin-top:10px"><span class="label">GRAND TOTAL:</span><input id="grandtotal" class="input" style="max-width:110px" readonly></div><label style="display:block;margin-top:10px"><span class="label">Configuración a utilizar</span><select id="configmode" class="select"><option>Calculada</option><option>Verificada</option></select></label><label style="display:block;margin-top:10px"><span class="label">Pallet configuration</span><textarea id="pconfig" class="textarea" readonly></textarea></label></div>
<div class="card"><h2 class="section-title">5. Carrier Costs & Pricing</h2><div class="carrier-grid">${carrierCard('WWE',['wwe_cost','wwe_add'],'WWE')}${carrierCard('CBCFS',['cbcfs_cost','cbcfs_add'],'CBCFS')}${carrierCard('UPS',['ups_dv','ups_sgn','ups_sm','ups_add'],'UPS')}${carrierCard('FedEx',['fedex_cost','fedex_add'],'FedEx')}${carrierCard('Uber Freight',['uber_cost','uber_add','uber_trucks'],'Uber Freight')}${carrierCard('LOCAL DELIVERY',['ld_cost1','ld_cost_extra','ld_pallets'],'LOCAL DELIVERY')}</div><div id="winner" class="winner" style="margin-top:12px">Ninguna - Faltan Costos</div></div>
<div class="card"><h2 class="section-title">6. Services</h2><input id="srv-search" class="input" placeholder="Search service"><div id="services" class="row" style="margin:10px 0;max-height:150px;overflow:auto"></div><textarea id="selected-services" class="textarea" placeholder="Selected services"></textarea><div class="row" style="margin-top:10px"><button class="btn secondary" id="clear-services">Clear Box</button><button class="btn success" id="save-quote">Guardar cotización</button><button class="btn primary hidden" id="update-quote">Actualizar cotización</button><button class="btn danger" id="clear-form">Limpiar todo</button></div></div>
<div class="card"><h2 class="section-title">Productos en esta Cotización</h2><div class="scroll-x"><table class="data-table" id="cart-table"><thead><tr><th>Producto</th><th>SKU</th><th>Qty</th><th>Price</th><th>Revenue</th><th>Winner</th><th></th></tr></thead><tbody></tbody></table></div><button class="btn secondary" id="add-cart" style="margin-top:10px">Agregar producto al quote</button></div>`}
function carrierCard(title,fields,kind){const id=kind.replace(/\W/g,'');let extra='';if(kind==='WWE'||kind==='CBCFS'){extra=`<label style="display:block;margin-top:8px"><span class="label">TRANSPORT</span><select id="${kind.toLowerCase()}_trans" class="select">${carriers.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>`}if(kind==='Uber Freight'){extra=`<label style="display:block;margin-top:8px"><span class="label">MODO</span><select id="uber_mode" class="select"><option>TL</option><option>LTL</option></select></label><label style="display:block;margin-top:8px"><span class="label">TRANSPORT</span><select id="uber_trans" class="select">${carriers.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>`}if(kind==='LOCAL DELIVERY'){extra=`<label style="display:block;margin-top:8px"><span class="label">LÍMITE ALTURA</span><select id="maxheight_carrier" class="select"><option>Altura Máxima: 90"</option><option>Altura Máxima: 41"</option><option>Altura Máxima: Personalizada</option></select></label><label style="display:block;margin-top:8px"><span class="label">DESTINO</span><input id="ld_address" class="input" readonly></label>`}return `<div class="carrier" id="card-${id}"><div class="between"><b>${title}</b><span class="pill" id="ship-${id}">$0.00</span></div>${extra}${fields.map(f=>`<label style="display:block;margin-top:8px"><span class="label">${f.replace(/_/g,' ').toUpperCase()}</span><input id="${f}" class="input" type="number" step="0.01"></label>`).join('')}<div class="muted" id="exact-${id}">Exact: $0.00</div></div>`}
function bindView(){if(state.tab==='quote')bindQuote(); if(state.tab==='quotes')bindQuotes(); if(['products','customers','verified_configs','rules'].includes(state.tab))bindCrud(state.tab); if(state.tab==='local')bindLocal(); if(state.tab==='reports')bindReports()}
function bindQuote(){loadEmail($('#qdate').value);setupCustomerAutocomplete();setupProductAutocomplete();setupServices();setupPallets();['pqty','pprice'].forEach(id=>$('#'+id).addEventListener('input',()=>{insured();checkVerified();applyRules();calcPallets()}));['qtype','qaddress','qcompany'].forEach(id=>$('#'+id).addEventListener('input',()=>{if(id==='qaddress'){$('#ld_address').value=$('#qaddress').value}applyRules()}));$('#prevenue').addEventListener('change',calc);['wwe_cost','wwe_add','cbcfs_cost','cbcfs_add','fedex_cost','fedex_add','uber_cost','uber_add','uber_trucks','ups_dv','ups_sgn','ups_sm','ups_add','ld_cost1','ld_cost_extra','ld_pallets'].forEach(id=>$('#'+id).addEventListener('input',calc));['uber_mode','wwe_trans','cbcfs_trans','uber_trans'].forEach(id=>$('#'+id)?.addEventListener('change',calc));$('#maxheight_carrier').addEventListener('change',()=>{$('#maxheight').value=$('#maxheight_carrier').value;$('#customheight').disabled=!$('#maxheight').value.includes('Personalizada');calcPallets()});$('#maxheight').addEventListener('change',()=>{$('#maxheight_carrier').value=$('#maxheight').value;$('#customheight').disabled=!$('#maxheight').value.includes('Personalizada');calcPallets()});$('#customheight').addEventListener('input',calcPallets);$('#qdate').addEventListener('change',e=>loadEmail(e.target.value));$('#add-cart').onclick=addCart;$('#clear-form').onclick=()=>{state.cart=[];state.edit=null;render()};$('#clear-services').onclick=()=>{$('#selected-services').value=''};$('#save-quote').onclick=saveQuote;$('#update-quote').onclick=saveQuote;renderCart();if(state.edit)hydrateEdit();else{$('#ld_pallets').value='1';$('#ld_cost_extra').value='20';$('#ld_address').value=$('#qaddress').value}calcPallets();calc()}
async function loadEmail(date){if(!sb)return;const {data,error}=await sb.from('quotes').select('email').eq('date',date);if(error)return;const vals=data.map(x=>parseInt(x.email)).filter(Number.isFinite);$('#qemail').value=String(vals.length?Math.max(...vals)+1:1)}
function setupCustomerAutocomplete(){const inp=$('#qcompany'),box=$('#suggestions');const draw=()=>{const term=norm(inp.value);const rows=state.customers.filter(c=>norm(c.company_name).includes(term)).slice(0,60);box.innerHTML=rows.map(c=>`<div class="suggestion" data-id="${c.id_cliente}">${esc(c.company_name)} <span class="pill">[${esc(c.id_code||'')}]</span><small>📍 ${esc(c.address)}</small></div>`).join('');box.classList.toggle('hidden',!term||!rows.length);box.querySelectorAll('.suggestion').forEach(el=>{el.onmouseenter=()=>showPreview(el,custById(el.dataset.id));el.onmouseleave=hidePreview;el.onclick=()=>selectCustomer(custById(el.dataset.id));});};inp.addEventListener('input',()=>{state.selectedCustomer=null;draw();applyRules()});inp.addEventListener('focus',draw);const addr=$('#qaddress');addr.addEventListener('input',()=>{const a=norm(addr.value).replace(/[,.]+/g,' ');if(a.length<5)return;const c=state.customers.find(x=>norm(x.address).replace(/[,.]+/g,' ')===a);if(c){state.selectedCustomer=c;$('#qcompany').value=c.company_name;$('#qtype').value=c.type||'Other';}});document.addEventListener('click',e=>{if(!e.target.closest('.autocomplete'))box.classList.add('hidden')},{once:true});}
function showPreview(el,c){let p=$('#customer-preview');if(!p){p=document.createElement('div');p.id='customer-preview';p.className='preview';document.body.appendChild(p)}p.innerHTML=`<b>${esc(c.company_name)}</b><br>📍 ${esc(c.address||'No address')}`;const r=el.getBoundingClientRect();p.style.left=Math.min(r.right+8,innerWidth-380)+'px';p.style.top=Math.min(r.top,innerHeight-120)+'px';p.style.display='block'}
function hidePreview(){const p=$('#customer-preview');if(p)p.style.display='none'}
function custById(id){return state.customers.find(c=>String(c.id_cliente)===String(id))}
function selectCustomer(c){state.selectedCustomer=c;$('#qcompany').value=c.company_name;$('#qaddress').value=c.address||'';$('#qtype').value=c.type||'Other';$('#selected-services').value=cleanServices(c.accessories||'');$('#suggestions').classList.add('hidden');if(localType(c.type)){$('#ld_cost1').value=num(c.local_delivery_cost_1);$('#ld_cost_extra').value=num(c.local_delivery_cost_extra)||20}applyRules();calc()}
function setupProductAutocomplete(){const inp=$('#pname'),box=$('#prod-suggestions');const draw=()=>{state.selectedProduct=null;const term=norm(inp.value);const rows=state.products.map((p,i)=>({p,i})).filter(x=>norm(x.p.product_list).includes(term)).slice(0,50);box.innerHTML=rows.map(x=>`<div class="suggestion" data-idx="${x.i}">${esc(x.p.product_list)}<small>${esc(x.p.sku)} · ${esc(x.p.category||'')}</small></div>`).join('');box.classList.toggle('hidden',!term||!rows.length);box.querySelectorAll('.suggestion').forEach(el=>el.onclick=()=>selectProduct(state.products[+el.dataset.idx]));};inp.addEventListener('input',draw);inp.addEventListener('focus',draw)}
function selectProduct(p){if(!p)return;state.selectedProduct=p;$('#pname').value=p.product_list;$('#psku').value=p.sku;$('#pweight').value=p.weight||'';$('#pheight').value=p.height||'';$('#pti').value=p.ti||'';$('#phi').value=p.hi||'';$('#ptihi').value=p.tihi||'';$('#pdims').value=p.dimensions||'';$('#prod-suggestions').classList.add('hidden');checkVerified();applyRules();calc()}
function setupServices(){const box=$('#services');const draw=()=>{const t=norm($('#srv-search').value);box.innerHTML=services.filter(x=>norm(x).includes(t)).map(x=>`<label class="pill"><input type="checkbox" value="${esc(x)}"> ${esc(x)}</label>`).join('')};$('#srv-search').oninput=draw;draw()}
function setupPallets(){if(!$('#pallets').children.length)addPallet();$('#add-pallet').onclick=()=>addPallet();$('#remove-pallet').onclick=()=>{const c=$('#pallets').children;if(c.length>1)c[c.length-1].remove();calcPallets()}}
function addPallet(){const d=document.createElement('div');d.className='grid g6';d.innerHTML=`<label><span class="label"># Pallet</span><input class="input pal" value="1"></label><label><span class="label"># Cases</span><input class="input cases"></label><label><span class="label"># Level</span><input class="input levels"></label><label><span class="label">Height</span><input class="input ph" readonly></label><label><span class="label">Weight</span><input class="input pw" readonly></label><label><span class="label">Total CS</span><input class="input pcs" readonly></label>`;$('#pallets').appendChild(d);d.querySelectorAll('input').forEach(x=>x.addEventListener('input',calcPallets));calcPallets()}
function calcPallets(){const h=num($('#pheight').value),hi=num($('#phi').value),w=num($('#pweight').value),tihi=num($('#ptihi').value);let grand=0,totalP=0,lines=[];let mode=$('#maxheight').value||'Altura Máxima: 90"',limit=mode.includes('41"')?41:mode.includes('Personalizada')?(num($('#customheight').value)||999):90;document.querySelectorAll('#pallets>div').forEach(d=>{const pal=num(d.querySelector('.pal').value),cs=num(d.querySelector('.cases').value),lev=num(d.querySelector('.levels').value);let hh=0,ww=0;if(lev>0&&hi>0){if(lev===hi)hh=h;else if(lev<hi)hh=(h/hi*lev)+5}if(cs>0&&cs<=tihi)ww=(cs*w)+42;const totcs=pal*cs,totalw=pal*ww;grand+=totcs;totalP+=pal;d.querySelector('.ph').value=hh?Math.round(hh):'';d.querySelector('.pw').value=ww?Math.round(ww*100)/100:'';d.querySelector('.pcs').value=totcs?Math.round(totcs):'';d.querySelector('.ph').style.background=hh>limit?'#ea4335':'#eaf2e8';d.querySelector('.ph').style.color=hh>limit?'white':'#137333';if(pal>0)lines.push(`${pal} P , ${totcs} cs (W: ${Math.round(totalw*100)/100} lbs, H: ${Math.round(hh)}")`)});$('#grandtotal').value=grand?Math.round(grand):'';$('#pconfig').value=lines.join(' +\n');$('#pallet-count').textContent=document.querySelectorAll('#pallets>div').length;const ver=$('#pverified').value||'';const m=/^(\d+)\s*P/i.exec(ver);const vp=m?num(m[1]):0;$('#ld_pallets').value=vp>0&&!mode.includes('41"')?vp:(totalP||1);calc()}
function insured(){const q=num($('#pqty').value),p=num($('#pprice').value);$('#pinsured').value=q&&p?'$'+(q*p).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):''}
async function checkVerified(){const p=$('#pname').value,q=$('#pqty').value;if(!p||!q)return;const {data}=await sb.from('verified_configs').select('*').eq('product_list',p).eq('quantity',q).order('id',{ascending:false}).limit(1);$('#pverified').value=data?.[0]?.verified_config||'No tiene verificado';}
function cleanServices(x){return String(x||'').split(',').map(s=>s.replace(/^\s*(WWE|CBCFS|WWE & CBCFS)\s*:\s*/i,'').trim()).filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', ')}
async function applyRules(){const company=norm($('#qcompany').value),address=norm($('#qaddress').value),prod=norm($('#pname').value),p=state.products.find(x=>norm(x.product_list)===prod),cat=norm(p?.category),tipo=norm(p?.product_type),qty=num($('#pqty').value);const all=[...carriers];let wwe=[...all],cbcfs=[...all],revenue='85',validation='';let disableWwe=localType($('#qtype').value),disableCbcfs=disableWwe,disableUber=disableWwe,disableUps=disableWwe,disableFedex=disableWwe;const rules=state.rules.filter(r=>norm(r.estado)==='ACTIVA'),generic=x=>['TODAS','TODAS LAS SEDES','TODOS','-',''].includes(norm(x)),matched=[];const specificClient=desc=>rules.some(rr=>norm(rr.categoria)==='CLIENTES'&&norm(rr.descripcion)===desc&&!generic(rr.sede_ubicacion)&&norm(rr.sede_ubicacion)!=='DEMÁS SEDES'&&address.includes(norm(rr.sede_ubicacion)));for(const r of rules){const rc=norm(r.categoria),desc=norm(r.descripcion),loc=norm(r.sede_ubicacion),crit=norm(r.criterio_busqueda);let score=null;if(rc==='GENERAL'){if(crit==='CATEGORÍA'&&cat&&desc.includes(cat))score=100;else if(crit==='TIPO'&&tipo&&desc.includes(tipo))score=100;else if(['NOMBRE EXACTO','-',''].includes(crit)&&prod&&desc.includes(prod))score=desc===prod?110:105}else if(rc==='PRODUCTOS'&&prod){if(crit==='CATEGORÍA'&&cat&&desc.includes(cat))score=200;else if(crit==='TIPO'&&tipo&&desc.includes(tipo))score=200;else if(['NOMBRE EXACTO','-',''].includes(crit)&&desc.includes(prod))score=desc===prod?230:220}else if(rc==='CLIENTES'&&company){const nm=desc===company||desc.includes(company)||(company.length>=4&&company.includes(desc));if(nm){if(generic(loc))score=320;else if(loc==='DEMÁS SEDES')score=specificClient(desc)?null:300;else if(loc&&address.includes(loc))score=360+Math.min(loc.length,80)}}if(score!=null)matched.push([score,r])}matched.sort((a,b)=>b[0]-a[0]);const cr=matched.find(x=>{const v=norm(x[1].carriers_permitidos);return v&&!['TODOS','-',''].includes(v)})?.[1];if(cr){const s=norm(cr.carriers_permitidos);const a=all.filter(c=>s.includes(norm(c)));if(a.length){wwe=[...a];cbcfs=[...a]}}for(const [score,r] of matched){if(norm(r.modo_envio).includes('SOLO LTL')){disableUps=true;disableFedex=true}const threshold=num(r.umbral_ups);if(threshold>0&&qty>threshold)disableUps=true;if(norm(r.requiere_validacion).includes('SÍ')||norm(r.requiere_validacion).includes('SI'))validation='⚠️ ATENCIÓN: Requiere validación según Maestro de Permisos.'}const revs=matched.map(([score,r])=>[score,String(r.revenue??'').trim()]).filter(([score,rv])=>/^[0-9.]+$/.test(rv)&&num(rv)>0);if(revs.length){const prodRevs=revs.filter(x=>x[0]>=200);revenue=(prodRevs.length?prodRevs:revs).sort((a,b)=>b[0]-a[0])[0][1]}$('#prevenue').value=revenue;$('#customer-warning').textContent=validation;[['WWE',disableWwe],['CBCFS',disableCbcfs],['UberFreight',disableUber],['UPS',disableUps],['FedEx',disableFedex]].forEach(([id,dis])=>$('#card-'+id)?.classList.toggle('disabled',dis));['wwe_trans','cbcfs_trans'].forEach((id,i)=>{const arr=i?wwe:cbcfs;const el=$('#'+id);if(el){const old=el.value;el.innerHTML=arr.map(x=>`<option>${esc(x)}</option>`).join('');if(arr.includes(old))el.value=old}});calc()}
function calc(){const rev=num($('#prevenue').value)||100,qty=num($('#pqty').value),data=[];const ship=(id,cost,add,disabled=false)=>{const ex=cost>0?(cost/rev*100+add):0;$('#ship-'+id).textContent=ex?'$'+Math.ceil(ex):'$0.00';$('#exact-'+id).textContent='Exact: $'+ex.toFixed(2);if(cost>0&&!disabled)data.push([id,cost+add,ex])};ship('WWE',num($('#wwe_cost').value),num($('#wwe_add').value),$('#card-WWE').classList.contains('disabled'));ship('CBCFS',num($('#cbcfs_cost').value),num($('#cbcfs_add').value),$('#card-CBCFS').classList.contains('disabled'));ship('FedEx',num($('#fedex_cost').value),num($('#fedex_add').value),$('#card-FedEx').classList.contains('disabled'));const uc=num($('#uber_cost').value),ua=num($('#uber_add').value),tr=Math.max(1,num($('#uber_trucks').value)||1),mode=$('#uber_mode').value||'TL';if(uc>0){const total=(uc+ua)*(mode==='LTL'?1:tr),ex=total/rev*100;$('#ship-UberFreight').textContent='$'+Math.ceil(ex);$('#exact-UberFreight').textContent='Exact: $'+ex.toFixed(2);if(!$('#card-UberFreight').classList.contains('disabled'))data.push([mode==='LTL'?'UBER FREIGHT LTL':'UBER FREIGHT TL',total,ex])}const ups=num($('#ups_dv').value)*qty+num($('#ups_sgn').value)*qty+num($('#ups_sm').value)*qty+num($('#ups_add').value)*qty,upsex=ups/rev*100;if(num($('#ups_sm').value)>0&&(num($('#ups_dv').value)===0||num($('#ups_sgn').value)===0)){$('#ship-UPS').textContent='Seguro/Firma faltante';$('#exact-UPS').textContent='Dato faltante'}else{$('#ship-UPS').textContent=ups?'$'+Math.ceil(upsex):'$0.00';$('#exact-UPS').textContent='Exact: $'+upsex.toFixed(2);if(ups>0&&!$('#card-UPS').classList.contains('disabled'))data.push(['UPS',ups,upsex])}let ld=0,ldsp=0;const plds=num($('#ld_pallets').value),c1=num($('#ld_cost1').value),ce=num($('#ld_cost_extra').value);if(plds>0&&c1>0){if(c1===40&&plds===1){ld=40;ldsp=70}else{ld=c1+Math.max(0,plds-1)*ce;ldsp=ld/80*100}}$('#ship-LOCALDELIVERY').textContent=ldsp?'$'+Math.ceil(ldsp):'$0.00';$('#exact-LOCALDELIVERY').textContent='Cost: $'+ld.toFixed(2)+' / SP $'+ldsp.toFixed(2);const local=localType($('#qtype').value);if(local&&ld>0){$('#winner').textContent=`LOCAL DELIVERY - Costo: $${ld.toFixed(2)}`;return {name:'LOCAL DELIVERY',cost:ld,sp:ldsp}}if(data.length){data.sort((a,b)=>a[1]-b[1]);let b=data[0];if(b[0]==='CBCFS'&&data[1]){const saving=((data[1][1]-b[1])/data[1][1])*100;if(saving<=5)b=data[1]}$('#winner').textContent=`${b[0]} - Costo: $${b[1].toFixed(2)}`;return {name:b[0],cost:b[1],sp:b[2]}}$('#winner').textContent='Ninguna - Faltan Costos';return {name:'',cost:0,sp:0}}
function addCart(){const p=state.selectedProduct||state.products.find(x=>x.product_list===$('#pname').value&&x.sku===$('#psku').value);if(!p){toast('Selecciona un producto',false);return}const w=calc();const form={sku:p.sku,product:p.product_list,qty:num($('#pqty').value),price_case:num($('#pprice').value),revenue:num($('#prevenue').value),insured:num($('#pinsured').value),weight:$('#pweight').value,height:$('#pheight').value,ti:$('#pti').value,hi:$('#phi').value,tihi:$('#ptihi').value,dims:$('#pdims').value,repack_mode:$('#prepack').value,bundle:$('#pbundle').value,verified_config:$('#pverified').value,pallet_config:$('#pconfig').value,wwe_cost:$('#wwe_cost').value,wwe_add:$('#wwe_add').value,wwe_ship:num($('#ship-WWE').textContent),wwe_trans:$('#wwe_trans').value,cbcfs_cost:$('#cbcfs_cost').value,cbcfs_add:$('#cbcfs_add').value,cbcfs_ship:num($('#ship-CBCFS').textContent),cbcfs_trans:$('#cbcfs_trans').value,fedex_cost:$('#fedex_cost').value,fedex_add:$('#fedex_add').value,fedex_ship:num($('#ship-FedEx').textContent),ups_dv:$('#ups_dv').value,ups_sgn:$('#ups_sgn').value,ups_sm:$('#ups_sm').value,ups_add:$('#ups_add').value,ups_ship:num($('#ship-UPS').textContent),uber_mode:$('#uber_mode').value,uber_trans:$('#uber_trans').value,uber_cost:$('#uber_cost').value,uber_add:$('#uber_add').value,uber_trucks:$('#uber_trucks').value,uber_ship:num($('#ship-UberFreight').textContent),ld_pallets:$('#ld_pallets').value,ld_cost1:$('#ld_cost1').value,ld_cost_extra:$('#ld_cost_extra').value,ld_ship:num($('#ship-LOCALDELIVERY').textContent),best_platform_name:w.name,best_platform_cost:w.cost,best_platform_sp:w.sp,services:$('#selected-services').value,nota:$('#pnota').value};state.cart.push(form);renderCart();toast('Producto agregado al quote')}
function renderCart(){const tb=$('#cart-table tbody');if(!tb)return;tb.innerHTML=state.cart.map((p,i)=>`<tr><td>${esc(p.product)}</td><td>${esc(p.sku)}</td><td>${p.qty}</td><td>$${num(p.price_case).toFixed(2)}</td><td>${p.revenue}%</td><td>${esc(p.best_platform_name||'')}</td><td><button class="btn danger" data-rm="${i}">X</button></td></tr>`).join('');tb.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{state.cart.splice(+b.dataset.rm,1);renderCart()})}
function payloadFromCart(p,g,iid){const local=localType(g.type),cfg=p.best_platform_name==='UPS'?`- (W: ${p.weight} lbs, D: ${p.dims})`:(p.verified_config&&p.verified_config.toLowerCase()!=='no tiene verificado'?`- ${p.verified_config} ✔️`:`- ${p.pallet_config||''}`),w=num(p.wwe_cost)+num(p.wwe_add),c=num(p.cbcfs_cost)+num(p.cbcfs_add),f=num(p.fedex_cost)+num(p.fedex_add),u=(num(p.ups_dv)+num(p.ups_sgn)+num(p.ups_sm)+num(p.ups_add))*num(p.qty),ub=(num(p.uber_cost)+num(p.uber_add))*((p.uber_mode||'TL')==='LTL'?1:Math.max(1,num(p.uber_trucks)));return {quote_instance_id:iid,id_registro:`${g.date.replaceAll('/','')}_${g.quote}P${String(p.sku).replace(/\s/g,'').slice(0,4).toUpperCase()}${p.qty}`,date:g.date,email:g.email,quote:g.quote,address:g.address,company_name:g.company,type:g.type,sku:p.sku,product:p.product,qty:p.qty,price_per_case:p.price_case,revenue:p.revenue,insured_value:p.insured,better_cost:p.best_platform_cost,better_shipping_price:Math.ceil(p.best_platform_sp),better_platform:p.best_platform_name,applied_configuration:cfg,cost_wwe:w,sp_wwe:num(p.wwe_ship),transport_wwe:p.wwe_trans||'',cost_ups:u,sp_ups:num(p.ups_ship),cost_cbcfs:c,sp_cbcfs:num(p.cbcfs_ship),transport_cbcfs:p.cbcfs_trans||'',cost_uber_freight_tl:(p.uber_mode||'TL')==='TL'?ub:0,sp_uber_freight_tl:(p.uber_mode||'TL')==='TL'?num(p.uber_ship):0,cost_uber_freight_ltl:(p.uber_mode||'TL')==='LTL'?ub:0,sp_uber_freight_ltl:(p.uber_mode||'TL')==='LTL'?num(p.uber_ship):0,transport_uber_freight_ltl:(p.uber_mode||'TL')==='LTL'?(p.uber_trans||''):'' ,cost_fedex:f,sp_fedex:num(p.fedex_ship),cost_local_delivery:local?num(p.best_platform_cost):0,sp_local_delivery:local?num(p.best_platform_sp):0,services:p.services||'',nota:p.nota||'',form_state:p,created_at:new Date().toISOString()}}
async function saveQuote(){if(!sb){toast('Configura Supabase primero',false);return}if(!$('#qnum').value.trim()||!state.cart.length){toast('Falta Quote o productos',false);return}const wasEdit=!!state.edit;if(wasEdit&&!navigator.onLine){toast('La edición de una cotización requiere conexión. Para trabajar sin internet usa el LogiSuite local y luego sincroniza.',false);return}const g={date:$('#qdate').value,email:$('#qemail').value,quote:$('#qnum').value.trim(),company:$('#qcompany').value.trim(),address:$('#qaddress').value.trim(),type:$('#qtype').value};const iid=state.edit?.quote_instance_id||crypto.randomUUID(),table=localType(g.type)?'local_quotes':'quotes';if(wasEdit){const {error}=await sb.from(table).delete().eq('quote_instance_id',iid);if(error){toast(error.message,false);return}}const rows=state.cart.map(p=>payloadFromCart(p,g,iid));if(!navigator.onLine){const pending=JSON.parse(localStorage.getItem('logisuite-pending')||'[]');pending.push({table,rows});localStorage.setItem('logisuite-pending',JSON.stringify(pending));toast('Sin internet: cotización guardada localmente y quedará pendiente de sincronizar');state.cart=[];state.edit=null;state.tab='quotes';render();return}const {error}=await sb.from(table).insert(rows);if(error){toast(error.message,false);return}toast(wasEdit?'Cotización actualizada':'Cotización guardada');state.cart=[];state.edit=null;state.tab='quotes';render()}
async function hydrateEdit(){const table=localType(state.edit.type)?'local_quotes':'quotes';const {data,error}=await sb.from(table).select('*').eq('quote_instance_id',state.edit.quote_instance_id).order('id');if(error||!data?.length)return;const r=data[0];$('#qdate').value=r.date;$('#qnum').value=r.quote;$('#qemail').value=r.email||'';$('#qcompany').value=r.company_name||'';$('#qaddress').value=r.address||'';$('#qtype').value=r.type||'Other';state.cart=data.map(x=>x.form_state||{sku:x.sku,product:x.product,qty:x.qty,price_case:x.price_per_case,revenue:x.revenue,insured:x.insured_value,best_platform_name:x.better_platform,best_platform_cost:x.better_cost,best_platform_sp:x.better_shipping_price,services:x.services});$('#save-quote').classList.add('hidden');$('#update-quote').classList.remove('hidden');renderCart()}
function quotesView(){return `<div class="card"><div class="between"><h2 class="section-title">View Quotes</h2><div class="row"><input id="vq" class="input" style="width:220px" placeholder="Quote / company / product"><input id="vf" class="input" type="date"><input id="vt" class="input" type="date"><button class="btn primary" id="search-quotes">Buscar</button></div></div><div id="quotes-table" class="scroll-x"></div></div>`}
function bindQuotes(){loadQuotes();$('#search-quotes').onclick=loadQuotes}
async function loadQuotes(){if(!sb)return;let {data:q}=await sb.from('quotes').select('quote_instance_id,date,quote,company_name,address,type').order('date',{ascending:false}).limit(1000);let {data:l}=await sb.from('local_quotes').select('quote_instance_id,date,quote,company_name,address,type').order('date',{ascending:false}).limit(1000);let rows=[...(q||[]),...(l||[])];const term=norm($('#vq').value),from=$('#vf').value,to=$('#vt').value;if(term)rows=rows.filter(r=>norm(r.quote).includes(term)||norm(r.company_name).includes(term)||norm(r.address).includes(term));if(from||to)rows=rows.filter(r=>{const [dd,mm,yy]=String(r.date||'').split('/');const iso=yy&&mm&&dd?`${yy}-${mm}-${dd}`:r.date;return (!from||iso>=from)&&(!to||iso<=to)});const groups=new Map();for(const r of rows){if(!groups.has(r.quote_instance_id))groups.set(r.quote_instance_id,r)}rows=[...groups.values()].slice(0,500);$('#quotes-table').innerHTML=`<table class="data-table"><thead><tr><th>DATE</th><th>QUOTE #</th><th>COMPANY OR NAME</th><th>ADDRESS</th><th>TYPE</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.quote)}</td><td>${esc(r.company_name)}</td><td>${esc(r.address)}</td><td>${esc(r.type)}</td><td class="quote-actions"><button class="btn secondary" data-open="${r.quote_instance_id}" data-mode="SP">View</button> <button class="btn warning" data-open="${r.quote_instance_id}" data-mode="COST">Cost</button> <button class="btn success" data-edit="${r.quote_instance_id}">Editar</button> <button class="btn danger" data-del="${r.quote_instance_id}">Delete</button></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPreview(b.dataset.open,b.dataset.mode));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editQuote(b.dataset.edit));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>deleteQuote(b.dataset.del))}
async function findQuote(iid){for(const t of ['quotes','local_quotes']){const {data}=await sb.from(t).select('*').eq('quote_instance_id',iid).order('id');if(data?.length)return {table:t,rows:data}}return null}
async function openPreview(iid,mode){const x=await findQuote(iid);if(!x)return;const r=x.rows[0];const modal=document.createElement('div');modal.className='modal-back';modal.innerHTML=`<div class="modal"><div class="between"><h2>Quote #${esc(r.quote)}</h2><button class="btn secondary close">Cerrar</button></div><p><b>${esc(r.company_name)}</b><br>${esc(r.address)}<br>Type: ${esc(r.type)}</p><div class="scroll-x"><table class="data-table"><thead><tr><th>SKU</th><th>PRODUCT</th><th>QTY</th><th>PRICE</th><th>REVENUE</th><th>PLATFORM</th><th>SHIPPING</th><th>CONFIGURATION</th></tr></thead><tbody>${x.rows.map(z=>`<tr><td>${esc(z.sku)}</td><td>${esc(z.product)}</td><td>${z.qty}</td><td>$${num(z.price_per_case).toFixed(2)}</td><td>${z.revenue}%</td><td>${esc(z.better_platform)}</td><td>$${num(z.better_shipping_price).toFixed(2)}</td><td>${esc(z.applied_configuration)}</td></tr>`).join('')}</tbody></table></div><div class="card" style="margin-top:12px"><b>${localType(r.type)?'LOCAL DELIVERY':''}</b><br>${esc(r.company_name)}<br>${esc(r.address)}</div></div>`;document.body.appendChild(modal);modal.querySelector('.close').onclick=()=>modal.remove()}
async function editQuote(iid){const x=await findQuote(iid);if(!x)return;const r=x.rows[0];state.edit=r;state.edit.table=x.table;state.tab='quote';render()}
async function deleteQuote(iid){if(!navigator.onLine){toast('Eliminar cotizaciones requiere conexión. Usa el sistema local si estás sin internet.',false);return}if(!confirm('¿Está segura de eliminar esta cotización?'))return;for(const t of ['quotes','local_quotes']){const {error}=await sb.from(t).delete().eq('quote_instance_id',iid);if(error){toast(error.message,false);return}}toast('Cotización eliminada');loadQuotes()}
function crudView(kind){const title={products:'Data Base · Productos_DB',customers:'Clientes',verified_configs:'Verificados',rules:'Reglas'}[kind];return `<div class="card"><div class="between"><h2 class="section-title">${title}</h2><div class="row"><input id="crud-q" class="input" style="width:260px" placeholder="Buscar"><button class="btn success" id="crud-new">Nuevo</button></div></div><div id="crud-table" class="scroll-x"></div></div>`}
async function bindCrud(kind){$('#crud-new').onclick=()=>editCrud(kind,null);$('#crud-q').oninput=()=>loadCrud(kind);loadCrud(kind)}
async function loadCrud(kind){const map={products:'products',customers:'customers',verified_configs:'verified_configs',rules:'rules'};const table=map[kind];const {data,error}=await sb.from(table).select('*').order(kind==='rules'?'id_regla':kind==='customers'?'company_name':kind==='products'?'product_list':'id',{ascending:false}).limit(300);if(error){toast(error.message,false);return}let rows=data||[];const t=norm($('#crud-q').value);if(t)rows=rows.filter(r=>JSON.stringify(r).toUpperCase().includes(t));const cols=rows[0]?Object.keys(rows[0]).filter(k=>!['created_at','form_state'].includes(k)).slice(0,10):[];$('#crud-table').innerHTML=`<table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}<th>ACTIONS</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}<td>${kind==='products'?`<button class="btn primary" data-cv="${i}" title="Ver ficha técnica">👁️</button> `:''}<button class="btn success" data-ce="${i}">Editar</button> <button class="btn danger" data-cd="${i}">Delete</button></td></tr>`).join('')}</tbody></table>`;$('#crud-table').querySelectorAll('[data-cv]').forEach(b=>b.onclick=()=>showProductFicha(rows[+b.dataset.cv]));$('#crud-table').querySelectorAll('[data-ce]').forEach(b=>b.onclick=()=>editCrud(kind,rows[+b.dataset.ce]));$('#crud-table').querySelectorAll('[data-cd]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Eliminar registro?'))return;const r=rows[+b.dataset.cd];const pk=kind==='products'?'id':kind==='customers'?'id_cliente':kind==='verified_configs'?'id':'id_regla';const {error}=await sb.from(table).delete().eq(pk,r[pk]);if(error)toast(error.message,false);else loadCrud(kind)})}
function showProductFicha(p){const fields=[['SKU','sku'],['CATEGORÍA','category'],['PRODUCTO','product'],['PAQUETE DE CAJA/UNTLS','package_units'],['PESO','weight'],['ALTURA','height'],['TI','ti'],['HI','hi'],['TIHI','tihi'],['DIMENSIONES','dimensions'],['INFORMACIÓN','information'],['NOTA','note']];const modal=document.createElement('div');modal.className='modal-back';modal.innerHTML=`<div class="modal ficha-modal" style="max-width:760px"><div class="between"><h2>FICHA TÉCNICA DEL PRODUCTO</h2><button class="btn secondary close">Cerrar</button></div><div class="card ficha-print" style="margin-top:10px"><h2 style="text-align:center;color:#e91e63">FICHA TÉCNICA DEL PRODUCTO</h2><div class="grid g2">${fields.map(([label,key])=>`<div><div class="label"><b>${esc(label)}</b></div><div class="input" style="min-height:18px;white-space:pre-wrap">${esc(p?.[key]??'')}</div></div>`).join('')}</div></div><div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn success print">🖨️ Imprimir / PDF</button></div></div>`;document.body.appendChild(modal);modal.querySelector('.close').onclick=()=>modal.remove();modal.querySelector('.print').onclick=()=>{const w=window.open('','_blank');w.document.write(`<html><head><title>Ficha Técnica - ${esc(p?.sku||'')}</title><style>body{font-family:Arial;padding:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.item{border:1px solid #ccc;padding:8px}.k{font-weight:bold}</style></head><body><h1 style="text-align:center;color:#e91e63">FICHA TÉCNICA DEL PRODUCTO</h1>${fields.map(([label,key])=>`<div class="item"><span class="k">${esc(label)}:</span> ${esc(p?.[key]??'')}</div>`).join('')}</body></html>`);w.document.close();w.focus();w.print()}}
function editCrud(kind,row){const fields={products:['sku','product_list','category','product_type','paper_oz','color','product','package_units','weight','height','ti','hi','tihi','dimensions','length_in','width_in','height_in','information','note'],customers:['id_code','type','company_name','address','accessories','local_delivery_cost_1','local_delivery_cost_extra'],verified_configs:['date','time','product_list','quantity','verified_config','information_source','category','product_type','package_units','dimensions','notes','status'],rules:['estado','fecha','categoria','criterio_busqueda','descripcion','sede_ubicacion','modo_envio','carriers_permitidos','umbral_ups','revenue','requiere_validacion','nota']}[kind];const back=state.tab;const modal=document.createElement('div');modal.className='modal-back';modal.innerHTML=`<div class="modal"><div class="between"><h2>${row?'Editar':'Nuevo'} ${kind}</h2><button class="btn secondary close">Cerrar</button></div><div class="grid g2">${fields.map(f=>`<label><span class="label">${esc(f)}</span><input class="input" data-f="${f}" value="${esc(row?.[f]??'')}"></label>`).join('')}</div><div class="row" style="margin-top:14px"><button class="btn success save">Guardar</button></div></div>`;document.body.appendChild(modal);modal.querySelector('.close').onclick=()=>modal.remove();modal.querySelector('.save').onclick=async()=>{const obj={};fields.forEach(f=>obj[f]=modal.querySelector(`[data-f="${CSS.escape(f)}"]`).value);const table=kind;const pk=kind==='products'?'id':kind==='customers'?'id_cliente':kind==='verified_configs'?'id':'id_regla';if(row)obj[pk]=row[pk];const {error}=await sb.from(table).upsert(obj,{onConflict:pk});if(error)toast(error.message,false);else{toast('Guardado');modal.remove();loadCrud(kind)}}}
function localView(){return `<div class="card"><h2 class="section-title">Local Delivery</h2><p class="muted">Historial de costos por sede.</p><div class="row"><input id="ldq" class="input" placeholder="Cliente, dirección o código"><button class="btn primary" id="ldsearch">Buscar</button></div><div id="ldtable" class="scroll-x" style="margin-top:12px"></div></div>`}
async function bindLocal(){const run=async()=>{const {data}=await sb.from('local_delivery_cost_history').select('*').or(`company_name.ilike.%${$('#ldq').value}%,address.ilike.%${$('#ldq').value}%,id_cliente_code.ilike.%${$('#ldq').value}%`).order('id',{ascending:false});$('#ldtable').innerHTML=`<table class="data-table"><thead><tr><th>DATE</th><th>COMPANY</th><th>ADDRESS</th><th>COST 1</th><th>EXTRA</th></tr></thead><tbody>${(data||[]).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.company_name)}</td><td>${esc(r.address)}</td><td>${r.cost_1}</td><td>${r.cost_extra}</td></tr>`).join('')}</tbody></table>`};$('#ldsearch').onclick=run;run()}
function reportsView(){return `<div class="card"><h2 class="section-title">Reportes</h2><div class="grid g3"><label><span class="label">Desde</span><input id="rf" class="input" type="date"></label><label><span class="label">Hasta</span><input id="rt" class="input" type="date"></label><label><span class="label">Quote opcional</span><input id="rq" class="input"></label></div><div class="row" style="margin-top:12px"><button class="btn primary" id="rdaily">Reporte diario</button><button class="btn secondary" id="rrange">Reporte por rango</button><button class="btn secondary" id="rquotes">Detalle de cotizaciones</button></div><div id="report-table" class="scroll-x" style="margin-top:14px"></div></div>`}
async function bindReports(){const run=async(kind)=>{let {data,error}=await sb.from('quotes').select('*').limit(5000);if(error)return;let rows=data||[];const from=$('#rf').value,to=$('#rt').value,q=$('#rq').value.trim();if(q)rows=rows.filter(r=>String(r.quote)===q);if(from||to)rows=rows.filter(r=>{const [dd,mm,yy]=String(r.date||'').split('/');const iso=yy&&mm&&dd?`${yy}-${mm}-${dd}`:r.date;return (!from||iso>=from)&&(!to||iso<=to)});if(kind==='daily'&&!from){const d=new Date();const today=`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;rows=rows.filter(r=>r.date===today)}$('#report-table').innerHTML=`<table class="data-table"><thead><tr><th>DATE</th><th>QUOTE</th><th>COMPANY</th><th>PRODUCT</th><th>QTY</th><th>PLATFORM</th><th>PRICE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.quote)}</td><td>${esc(r.company_name)}</td><td>${esc(r.product)}</td><td>${r.qty}</td><td>${esc(r.better_platform)}</td><td>$${num(r.better_shipping_price).toFixed(2)}</td></tr>`).join('')}</tbody></table>`};$('#rdaily').onclick=()=>run('daily');$('#rrange').onclick=()=>run('range');$('#rquotes').onclick=()=>run('quotes')}
async function login(){if(!ready){document.body.innerHTML='<div class="login"><div class="login-card"><h1>LogiSuite</h1><p>Configura <b>config.js</b> con la URL y publishable/anon key de Supabase.</p></div></div>';return}const html=`<div class="login"><div class="login-card"><h1>LogiSuite</h1><p class="muted">Inicia sesión</p><form id="lf"><label><span class="label">Usuario o correo</span><input id="lu" class="input" autocomplete="username" required></label><label style="display:block;margin-top:10px"><span class="label">Contraseña</span><div class="password-wrap"><input id="lp" class="input" type="password" autocomplete="current-password" required><button type="button" id="toggle-password" class="password-eye" aria-label="Mostrar contraseña">👁️</button></div></label><div id="lm" class="muted" style="margin:10px 0"></div><button class="btn primary" style="width:100%;margin-top:10px">Entrar</button><button type="button" id="forgot" class="btn secondary" style="width:100%;margin-top:8px">Olvidé mi contraseña</button></form></div></div>`;document.body.innerHTML=html;$("#toggle-password").onclick=()=>{const p=$("#lp"),b=$("#toggle-password"),show=p.type==="password";p.type=show?"text":"password";b.textContent=show?"🙈":"👁️";b.setAttribute("aria-label",show?"Ocultar contraseña":"Mostrar contraseña")};$('#lf').onsubmit=async e=>{e.preventDefault();let u=$('#lu').value.trim();if(u.toLowerCase()==='mjmm')u='morammariaj@gmail.com';const {data,error}=await sb.auth.signInWithPassword({email:u,password:$('#lp').value});if(error)$('#lm').textContent=error.message;else start(data.session)};$('#forgot').onclick=async()=>{const email='morammariaj@gmail.com';const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.href.split('#')[0]+'#reset'});$('#lm').textContent=error?error.message:'Te enviamos el enlace de recuperación al correo registrado.'}}
async function logout(){await sb?.auth.signOut();state.session=null;login()}
async function start(session){state.session=session;await bootstrap();render()}
async function bootstrap(){if(!sb)return;try{const [p,c,v,r]=await Promise.all([sb.from('products').select('*').order('product_list'),sb.from('customers').select('*').order('company_name').order('address'),sb.from('verified_configs').select('*').order('id',{ascending:false}),sb.from('rules').select('*').order('id_regla')]);if(p.error||c.error||v.error||r.error)throw new Error('offline');state.products=p.data||[];state.customers=c.data||[];state.verified=v.data||[];state.rules=r.data||[];localStorage.setItem('logisuite-cache',JSON.stringify({products:state.products,customers:state.customers,verified:state.verified,rules:state.rules}));}catch(e){try{const x=JSON.parse(localStorage.getItem('logisuite-cache')||'{}');state.products=x.products||[];state.customers=x.customers||[];state.verified=x.verified||[];state.rules=x.rules||[];}catch(_){}}window.addEventListener('online',async()=>{state.online=true;render();await syncPending()});window.addEventListener('offline',()=>{state.online=false;render()})}
async function syncPending(){const pending=JSON.parse(localStorage.getItem('logisuite-pending')||'[]');if(!pending.length||!sb||!navigator.onLine)return;const rest=[];for(const x of pending){try{const {error}=await sb.from(x.table).insert(x.rows);if(error)rest.push(x)}catch(e){rest.push(x)}}localStorage.setItem('logisuite-pending',JSON.stringify(rest));if(!rest.length)toast('Cambios offline sincronizados')}

function isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true||document.referrer.startsWith('android-app://')}
function isMobileOrTablet(){const ua=navigator.userAgent||'';const touch=navigator.maxTouchPoints||0;return /Android|iPhone|iPad|iPod|Mobile|Tablet/i.test(ua)||(touch>1&&Math.min(screen.width,screen.height)<=1024)}
function setupInstallInvite(){
  const show=()=>{
    if(!isMobileOrTablet()||isStandalone())return;
    let box=document.getElementById('install-invite');
    if(!box){
      box=document.createElement('div');box.id='install-invite';box.className='install-invite';
      box.innerHTML='<div class="install-icon"><img src="icon-192.svg" alt="" /></div><div class="install-copy"><b>Instala LogiSuite</b><span id="install-text">Ten tus cotizaciones siempre a mano, como una app.</span></div><button id="install-now" class="btn primary">Instalar</button><button id="install-close" class="install-close" aria-label="Cerrar">×</button>';
      document.body.appendChild(box);
      box.querySelector('#install-close').onclick=()=>box.remove();
      box.querySelector('#install-now').onclick=installApp;
    }
    const btn=box.querySelector('#install-now'),txt=box.querySelector('#install-text');
    if(/iPhone|iPad|iPod/i.test(navigator.userAgent)){
      txt.textContent='En Safari: toca Compartir → Agregar a pantalla de inicio.';
      btn.textContent='Cómo instalar';
      btn.onclick=()=>alert('En Safari toca Compartir y luego “Agregar a pantalla de inicio”.');
    }else if(state.installPrompt){
      btn.textContent='Instalar';
      btn.onclick=installApp;
    }else{
      btn.textContent='Instalar';
      btn.onclick=()=>alert('Cuando Chrome muestre la opción de instalación, toca “Instalar app”.');
    }
  };
  if(!isStandalone())setTimeout(show,900);
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;show()});
  window.addEventListener('appinstalled',()=>{state.installPrompt=null;document.getElementById('install-invite')?.remove();toast('LogiSuite instalada correctamente')});
}
async function installApp(){
  if(!state.installPrompt){
    if(/iPhone|iPad|iPod/i.test(navigator.userAgent)){alert('En Safari toca Compartir y luego “Agregar a pantalla de inicio”.');return}
    toast('La opción de instalación aparecerá cuando el navegador la habilite.',false);return;
  }
  const p=state.installPrompt;state.installPrompt=null;
  try{await p.prompt();await p.userChoice}catch(_){}
  document.getElementById('install-invite')?.remove();
}

function isStandalone(){return window.matchMedia?.("(display-mode: standalone)").matches||window.navigator.standalone===true||document.referrer.startsWith("android-app://");}
function isMobileOrTablet(){const ua=navigator.userAgent||"";return /Android|iPhone|iPad|iPod|Mobile|Tablet/i.test(ua)||(navigator.maxTouchPoints>1&&Math.min(screen.width,screen.height)<=1024);}
async function installApp(){if(!state.installPrompt){toast("En Chrome: menú ⋮ → Instalar aplicación.",false);return}const p=state.installPrompt;state.installPrompt=null;try{await p.prompt();await p.userChoice}catch(_){}} 
function setupInstallInvite(){const show=()=>{if(!isMobileOrTablet()||isStandalone())return;let x=$("#install-invite");if(!x){x=document.createElement("div");x.id="install-invite";x.className="install-invite";x.innerHTML='<div class="install-icon"><img src="icon-192.svg" alt=""></div><div class="install-copy"><b>Instala LogiSuite</b><span id="install-text">Úsala como una app y ten las cotizaciones a mano.</span></div><button id="install-now" class="btn btn-primary btn-sm">Instalar</button><button id="install-close" class="install-close">×</button>';document.body.appendChild(x);$("#install-close").onclick=()=>x.remove();$("#install-now").onclick=installApp;}if(/iPhone|iPad|iPod/i.test(navigator.userAgent)){$("#install-text").textContent="Safari: Compartir → Agregar a pantalla de inicio."}else if(state.installPrompt){$("#install-now").textContent="Instalar";$("#install-now").onclick=installApp;}};setTimeout(show,900);window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();state.installPrompt=e;show()});window.addEventListener("appinstalled",()=>{$("#install-invite")?.remove();toast("LogiSuite instalada correctamente")});}

function showChangePassword(){const m=document.createElement('div');m.className='modal-back';m.innerHTML=`<div class="modal" style="max-width:430px"><div class="between"><h2>Cambiar contraseña</h2><button class="btn secondary close">Cerrar</button></div><label><span class="label">Nueva contraseña</span><input id="cp1" class="input" type="password"></label><label style="display:block;margin-top:10px"><span class="label">Repetir contraseña</span><input id="cp2" class="input" type="password"></label><div id="cpm" class="muted" style="margin:10px 0"></div><button class="btn success" id="cps">Guardar</button></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=()=>m.remove();m.querySelector('#cps').onclick=async()=>{const a=m.querySelector('#cp1').value,b=m.querySelector('#cp2').value;if(a!==b){m.querySelector('#cpm').textContent='Las contraseñas no coinciden';return}const {error}=await sb.auth.updateUser({password:a});m.querySelector('#cpm').textContent=error?error.message:'Contraseña actualizada';if(!error)setTimeout(()=>m.remove(),900)}}
async function init(){setupInstallInvite();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!sb){login();return}const {data}=await sb.auth.getSession();if(data.session)start(data.session);else login();sb.auth.onAuthStateChange((e,s)=>{if(e==='SIGNED_OUT')login();if(e==='PASSWORD_RECOVERY')showReset()});if(location.hash==='#reset')showReset()}
function showReset(){const m=document.createElement('div');m.className='modal-back';m.innerHTML=`<div class="modal" style="max-width:420px"><h2>Cambiar contraseña</h2><label><span class="label">Nueva contraseña</span><input id="np" class="input" type="password"></label><label style="display:block;margin-top:10px"><span class="label">Repetir contraseña</span><input id="np2" class="input" type="password"></label><div id="nm" class="muted" style="margin:10px 0"></div><button class="btn success" id="nps">Guardar</button></div>`;document.body.appendChild(m);m.querySelector('#nps').onclick=async()=>{if($('#np').value!==$('#np2').value){$('#nm').textContent='Las contraseñas no coinciden';return}const {error}=await sb.auth.updateUser({password:$('#np').value});$('#nm').textContent=error?error.message:'Contraseña actualizada correctamente';if(!error)setTimeout(()=>m.remove(),1000)}}
init();